template(name="tmpl-sshd" type="string"
         string="%TIMESTAMP:::date-rfc3339% %HOSTNAME% sshd: %msg%\n")

if $programname == 'sshd' then {
    action(type="omfile" file="/var/log/sshd.log" template="tmpl-sshd")
    stop
}

/var/log/wtmp {
    monthly
    create 0664 root utmp
    rotate 1
}
/var/log/btmp {
    missingok
    monthly
    create 0600 root utmp
    rotate 1
}

# Logstash（采集管道层统一替换，日志第一落盘后、进库前完成）
filter {
  mutate {
    gsub => [
      "message", "(password|passwd|token|secret|api[_-]?key)=[^&\\s]+", "\\1=***"
    ]
  }
}
